<?php
declare(strict_types=1);
namespace App\Application\Taxonomy\Service;
use App\Application\Study\Port\TransactionManagerInterface;use App\Application\Taxonomy\DTO\Request\MergeTaxonomySubjectsRequestDto;use App\Domain\Taxonomy\Entity\TaxonomySubject;use App\Domain\Taxonomy\Entity\TaxonomySubjectMerge;use App\Domain\Taxonomy\Repository\TaxonomySubjectMergeApplierInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectMergeRepositoryInterface;use App\Domain\Taxonomy\Repository\TaxonomySubjectRepositoryInterface;
final class MergeTaxonomySubjectsService { public function __construct(private readonly TaxonomySubjectRepositoryInterface $subjects,private readonly TaxonomySubjectMergeApplierInterface $applier,private readonly TaxonomySubjectMergeRepositoryInterface $merges,private readonly TransactionManagerInterface $transactions){} public function merge(MergeTaxonomySubjectsRequestDto $input):void{$this->transactions->transactional(function()use($input){if($input->sourceSubjectId===$input->targetSubjectId)throw new \DomainException('Os assuntos devem ser diferentes.');$source=$this->subjects->findById($input->sourceSubjectId);$target=$this->subjects->findById($input->targetSubjectId);if($source===null||$target===null)throw new \DomainException('Assunto nao encontrado.');if($this->subjects->hasChildren($source->id))throw new \DomainException('Assunto de origem possui filhos.');$this->applier->reassignCanonicalReferences($source->id,$target->id);$this->subjects->save(new TaxonomySubject($source->id,$source->parentId,$source->name,$source->slug,$source->description,$source->level,false));$this->merges->save(new TaxonomySubjectMerge($this->uuid(),$source->id,$target->id,$input->mergedBy,trim($input->reason)));});} private function uuid():string{return bin2hex(random_bytes(16));} }
